<style>.step{margin-bottom:20px}.order-context{display:flex;justify-content:space-between;gap:12px;margin:0 22px 18px;padding:14px;border:1px solid #e2d5ae;border-radius:10px;background:#fffdf7}.order-context span{color:#6f6254}.panel-header{display:flex;justify-content:space-between}.types{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:20px 22px}.types label{padding:14px;border:1px solid #e2d5ae;border-radius:10px}.step>label,.step>#table-field{display:block;margin:0 22px 18px}.delivery-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:0 22px 18px}.delivery-fields[hidden]{display:none}.delivery-fields label{display:block}.delivery-fields input{display:block;width:100%;margin-top:6px;padding:10px;border:1px solid #d7c89e;border-radius:8px;background:#fffdf7}.delivery-fields span{font-weight:400;color:#6f6254}.step label>select,.step label>textarea,.step>label>textarea{display:block;width:100%;margin-top:6px;padding:10px;border:1px solid #d7c89e;border-radius:8px;background:#fffdf7}.tools{display:flex;gap:8px;padding:0 22px 18px}.tools input,.tools select{padding:10px;border:1px solid #d7c89e;border-radius:8px;background:#fffdf7}.tools input{flex:1}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;padding:0 22px 22px}.card{padding:15px;border:1px solid #e2d5ae;border-radius:12px;background:#fffdf7}.card[hidden]{display:none!important}.card.selected{border-color:#777;box-shadow:0 7px 20px rgba(0,0,0,.07)}.card h3{margin:5px 0}.card p{font-size:.8rem;color:#6f6254;min-height:32px}.bottom{display:flex;justify-content:space-between;align-items:center;gap:8px}.qty{display:flex;border:1px solid #d7c89e;border-radius:8px;overflow:hidden}.qty button{width:32px;border:0;background:#f6ecd0;font-size:18px}.qty input{width:38px;border:0;text-align:center;background:#fff}.options{margin-top:12px;padding:10px;background:#f7f7f5;border-radius:8px}.options[hidden],.note[hidden]{display:none}.options label{font-size:.72rem;font-weight:750}.note{margin-top:10px}.note textarea{width:100%;min-height:50px;border:1px solid #d7c89e;border-radius:8px;padding:7px}.summary{margin:0 22px 20px;padding:14px;background:#f8e7ae;border-radius:10px}.summary-line{display:flex;justify-content:space-between;padding:5px 0;gap:12px}.summary-line small{display:block;color:#6f6254}.summary-fee{border-top:1px dashed #cbbd95;margin-top:8px;padding-top:8px}.form-actions{margin:0 22px}.form-actions .button{margin-right:6px}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.grid,.types{grid-template-columns:1fr}.tools{flex-direction:column}.form-actions{display:grid;grid-template-columns:1fr 1.3fr}.form-actions .button{margin:0}}
