<script>
const form=document.getElementById('manual-order-form'),submit=document.getElementById('submit'),summary=document.getElementById('summary'),search=document.getElementById('product-search'),filter=document.getElementById('category-filter');
const comboBeverages=@json($comboBeverages);
const money=v=>'$'+Number(v).toLocaleString('es-CO',{maximumFractionDigits:0});
function applyProductFilters(){const q=search.value.trim().toLowerCase(),category=filter.value;let visibleCount=0;document.querySelectorAll('#product-grid .card').forEach(card=>{const name=card.dataset.name||'',categoryId=String(card.dataset.category||''),categoryName=card.querySelector('.eyebrow')?.textContent?.toLowerCase()||'',matchesSearch=!q||name.includes(q)||categoryName.includes(q),matchesCategory=!category||categoryId===String(category);const visible=matchesSearch&&matchesCategory;card.hidden=!visible;if(visible)visibleCount++;});document.getElementById('products-empty').hidden=visibleCount>0;}
search.addEventListener('input',applyProductFilters);filter.addEventListener('change',applyProductFilters);
function refresh(){let total=0,units=0,packaging=0,lines=[];const type='{{ $order->type?->value }}';const takeaway=type==='PARA_LLEVAR';const delivery=type==='DOMICILIO';document.querySelectorAll('.card').forEach(c=>{const i=c.querySelector('input[data-id]'),q=Number(i.value)||0;c.classList.toggle('selected',q>0);const n=c.querySelector('.note'),o=c.querySelector('.beverage'),comboChoice=c.querySelector('.combo-choice'),comboExtra=c.querySelector('.combo-extra');if(n)n.hidden=q===0;if(o)o.hidden=q===0;if(comboChoice&&comboExtra)comboExtra.hidden=q===0||comboChoice.value!=='SI';if(q){let price=Number(i.dataset.price),detail='';if(i.dataset.juice==='1'){const prep=c.querySelector('[name^="juice_preparation"]')?.value||'AGUA';price=prep==='LECHE'?9500:8500;detail=(prep==='LECHE'?'En leche':'En agua')+' · '+(c.querySelector('[name^="juice_fruit"]')?.selectedOptions[0]?.text||'');}else if(comboChoice?.value==='SI'){const t=c.querySelector('[data-combo-type]')?.selectedOptions[0]?.text||'',f=c.querySelector('[data-combo-flavor]')?.value||'';price+=10000;detail='COMBO +$10.000 · Papas a la francesa · '+t+' · '+f;}else{detail=c.querySelector('.beverage select')?.value||'';}const line=q*price,fee=(takeaway||delivery)&&c.dataset.packaging==='1'?1500*q:0;total+=line;packaging+=fee;units+=q;lines.push('<div class="summary-line"><span>'+q+' × '+c.querySelector('h3').textContent+'<small>'+detail+'</small></span><strong>'+money(line)+'</strong></div>');}});document.getElementById('items-count').textContent=units+' producto'+(units===1?'':'s')+' seleccionado'+(units===1?'':'s');const feeLine=(takeaway||delivery)&&packaging?'<div class="summary-line summary-fee"><span>Empaques para llevar</span><strong>'+money(packaging)+'</strong></div>':'';summary.innerHTML=lines.length?lines.join('')+feeLine+'<div class="summary-line"><strong>Total de esta adición</strong><strong>'+money(total+packaging)+'</strong></div>':'Agrega productos para ver el resumen.';submit.disabled=units===0;}document.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>{const i=document.querySelector(`input[data-id="${b.dataset.plus}"]`);i.value=Math.min(99,Number(i.value)+1);refresh()});document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{const i=document.querySelector(`input[data-id="${b.dataset.minus}"]`);i.value=Math.max(0,Number(i.value)-1);refresh()});document.querySelectorAll('.beverage select,.juice select,.combo-choice,[data-combo-type],[data-combo-flavor]').forEach(s=>s.addEventListener('change',()=>{if(s.matches('.combo-choice')){const id=s.dataset.id,extra=document.querySelector(`[data-combo-extra="${id}"]`);if(extra)extra.hidden=s.value!=='SI';}if(s.matches('[data-combo-type]')){const id=s.getAttribute('data-combo-type'),flavor=document.querySelector(`[data-combo-flavor="${id}"]`),flavors=comboBeverages[s.value]?.flavors||[];if(flavor)flavor.innerHTML=flavors.map(value=>`<option value="${value}">${value}</option>`).join('');}refresh();}));document.querySelectorAll('.card .note textarea').forEach(t=>t.addEventListener('input',refresh));refresh();applyProductFilters();
</script>
